mapper.select:
SELECT *, ( 6371 * acos( cos(radians(#{lat})) * cos(radians(latitude)) * cos(radians(longitude) - radians(#{lng})) + sin(radians(#{lat})) * sin(radians(latitude)) ) ) AS distance FROM heritage_sites WHERE status = 1 ORDER BY
(city_code = #{cityCode}) DESC,
CASE level WHEN '国家级' THEN 1 WHEN '省级' THEN 2 WHEN '市级' THEN 3 ELSE 4 END ASC, distance ASC LIMIT #{limit}
